// ═══ supplyAsync — returns result ═══
CompletableFuture<BigDecimal> balanceCF = CompletableFuture.supplyAsync(() -> {
    return accountRepo.getBalance("SAV2001");  // returns BigDecimal!
});
BigDecimal balance = balanceCF.get();  // blocks until result ready

// With custom executor:
CompletableFuture<BigDecimal> cf2 = CompletableFuture.supplyAsync(
    () -> accountRepo.getBalance("SAV2001"),
    ioPool  // custom pool instead of ForkJoinPool!
);

// Chain transformations:
CompletableFuture<String> report = CompletableFuture
    .supplyAsync(() -> getBalance("SAV2001"))       // CF<BigDecimal>
    .thenApply(bal -> bal.multiply(interestRate))     // CF<BigDecimal>
    .thenApply(interest -> "Interest: Rs." + interest); // CF<String>

// ═══ runAsync — no return (fire-and-forget) ═══
CompletableFuture<Void> notifyCF = CompletableFuture.runAsync(() -> {
    notificationService.sendSMS("Rajesh", "Trade settled");
    // void! No return value.
});
notifyCF.get();  // null! (Void)

// Chain side-effects:
CompletableFuture.runAsync(() -> auditLog("Trade TRD-001 settled"))
    .thenRun(() -> updateDashboard())
    .thenRun(() -> System.out.println("All done"));
// Each thenRun: Runnable (void), no result passed between stages.

// ═══ CANNOT chain thenApply after runAsync meaningfully ═══
CompletableFuture.runAsync(() -> sendNotification())
    .thenApply(v -> "result");  // v is null (Void)! Not useful.
// If you need a result → use supplyAsync!
