package com.bank.supplyrun;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class SupplyVsRunTest {

    // ═══ supplyAsync: returns result ═══
    @Test
    void supplyAsync_returnsResult() throws Exception {
        CompletableFuture<Integer> cf = CompletableFuture.supplyAsync(() -> 100000);
        assertThat(cf.get()).isEqualTo(100000);
    }

    // ═══ runAsync: returns Void (null) ═══
    @Test
    void runAsync_returnsVoid() throws Exception {
        AtomicBoolean executed = new AtomicBoolean(false);
        CompletableFuture<Void> cf = CompletableFuture.runAsync(
            () -> executed.set(true));
        Void result = cf.get();
        assertThat(result).isNull();  // Void!
        assertThat(executed.get()).isTrue();
    }

    // ═══ supplyAsync with custom executor ═══
    @Test
    void supplyAsync_customExecutor() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        AtomicReference<String> threadName = new AtomicReference<>();

        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> {
            threadName.set(Thread.currentThread().getName());
            return "done";
        }, pool);

        cf.get();
        assertThat(threadName.get()).startsWith("pool-");  // custom pool!
        pool.shutdown();
    }

    // ═══ Both in parallel: supply + run ═══
    @Test
    void parallel_supplyAndRun() throws Exception {
        AtomicBoolean notified = new AtomicBoolean(false);

        CompletableFuture<Integer> settlement = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(100); } catch (InterruptedException e) { }
            return 50000;  // settlement amount
        });

        CompletableFuture<Void> notification = CompletableFuture.runAsync(() -> {
            try { Thread.sleep(100); } catch (InterruptedException e) { }
            notified.set(true);  // fire-and-forget
        });

        long start = System.currentTimeMillis();
        CompletableFuture.allOf(settlement, notification).get();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(settlement.get()).isEqualTo(50000);
        assertThat(notified.get()).isTrue();
        assertThat(elapsed).isLessThan(300);  // parallel: ~100ms!
    }
}
